'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { validateRange, overlaps, nightsByMonth } = require('./src/range.js');
const { quoteStay } = require('./src/booking.js');

test('s1 an inverted range is rejected and a forward range still passes', () => {
  const backwards = validateRange('2026-04-18', '2026-04-11');
  assert.strictEqual(backwards.ok, false, 'check-out before check-in must be rejected');
  assert.ok(typeof backwards.reason === 'string' && backwards.reason.length > 0, 'rejection carries a reason');

  // A second, unrelated inverted pair: ordering has to be a rule, not a
  // special case sitting on top of one pair of dates.
  const alsoBackwards = validateRange('2027-09-02', '2027-08-30');
  assert.strictEqual(alsoBackwards.ok, false, 'any end-before-start range is rejected');
  assert.ok(typeof alsoBackwards.reason === 'string' && alsoBackwards.reason.length > 0, 'rejection carries a reason');

  const forwards = validateRange('2026-04-11', '2026-04-18');
  assert.strictEqual(forwards.ok, true, 'a normal forward range stays valid');
  assert.strictEqual(forwards.nights, 7);

  const oneNight = validateRange('2026-11-05', '2026-11-06');
  assert.strictEqual(oneNight.ok, true, 'a one night stay stays valid');
  assert.strictEqual(oneNight.nights, 1);
});

test('s2 a stay over the 30 night cap is rejected and exactly 30 is allowed', () => {
  const overCap = validateRange('2026-01-01', '2026-02-15');
  assert.strictEqual(overCap.ok, false, '45 nights is over the cap');
  assert.ok(typeof overCap.reason === 'string' && overCap.reason.length > 0, 'rejection carries a reason');

  // The boundary itself, one night either side of the cap.
  const justOver = validateRange('2026-06-01', '2026-07-02');
  assert.strictEqual(justOver.ok, false, '31 nights is over the cap');

  const atCap = validateRange('2026-01-01', '2026-01-31');
  assert.strictEqual(atCap.ok, true, 'exactly 30 nights is still allowed');
  assert.strictEqual(atCap.nights, 30);

  const wellUnder = validateRange('2026-06-01', '2026-06-04');
  assert.strictEqual(wellUnder.ok, true, 'a short stay is untouched by the cap');
  assert.strictEqual(wellUnder.nights, 3);
});

test('s3 a same day range is valid with zero nights', () => {
  const sameDay = validateRange('2026-03-09', '2026-03-09');
  assert.strictEqual(sameDay.ok, true, 'a day-use booking is a valid range');
  assert.strictEqual(sameDay.nights, 0);

  // Any same-day pair, not one hard-coded date.
  const anotherSameDay = validateRange('2026-12-24', '2026-12-24');
  assert.strictEqual(anotherSameDay.ok, true, 'a day-use booking is a valid range');
  assert.strictEqual(anotherSameDay.nights, 0);
});

test('s4 every rejection carries a machine readable code beside its reason', () => {
  const inverted = validateRange('2026-04-18', '2026-04-11');
  assert.strictEqual(inverted.code, 'inverted');
  assert.ok(typeof inverted.reason === 'string' && inverted.reason.length > 0, 'the code sits beside the reason, it does not replace it');

  const alsoInverted = validateRange('2027-09-02', '2027-08-30');
  assert.strictEqual(alsoInverted.code, 'inverted');

  const tooLong = validateRange('2026-01-01', '2026-02-15');
  assert.strictEqual(tooLong.code, 'too_long');
  assert.ok(typeof tooLong.reason === 'string' && tooLong.reason.length > 0, 'the code sits beside the reason, it does not replace it');

  const badFormat = validateRange('2026-01-01', 'next friday');
  assert.strictEqual(badFormat.ok, false);
  assert.strictEqual(badFormat.code, 'bad_format');
  assert.ok(typeof badFormat.reason === 'string' && badFormat.reason.length > 0, 'the code sits beside the reason, it does not replace it');

  const alsoBadFormat = validateRange('11/03/2026', '2026-03-14');
  assert.strictEqual(alsoBadFormat.code, 'bad_format');

  // A successful result keeps the shape it already had: no rejection code.
  const accepted = validateRange('2026-04-11', '2026-04-18');
  assert.strictEqual(accepted.ok, true);
  assert.strictEqual(accepted.nights, 7);
  assert.ok(!accepted.code, 'a valid range carries no rejection code');
});

test('s5 a date that is not a real calendar day is rejected as bad_format', () => {
  const impossible = ['2026-02-30', '2026-04-31', '2026-13-01', '2026-00-10', '2026-01-00', '2027-02-29'];
  for (const bad of impossible) {
    const asStart = validateRange(bad, '2029-12-20');
    assert.strictEqual(asStart.ok, false, bad + ' is not a day on any calendar');
    assert.strictEqual(asStart.code, 'bad_format', bad + ' is rejected as bad_format, not rolled forward');

    const asEnd = validateRange('2026-01-05', bad);
    assert.strictEqual(asEnd.ok, false, bad + ' is not a day on any calendar');
    assert.strictEqual(asEnd.code, 'bad_format', bad + ' is rejected as bad_format, not rolled forward');
  }

  // Real days near the awkward edges are untouched.
  const overLeapDay = validateRange('2028-02-28', '2028-03-01');
  assert.strictEqual(overLeapDay.ok, true, '2028 does have a 29th of February');
  assert.strictEqual(overLeapDay.nights, 2);

  const fromLeapDay = validateRange('2028-02-29', '2028-03-02');
  assert.strictEqual(fromLeapDay.ok, true, 'a genuine leap day is a bookable date');
  assert.strictEqual(fromLeapDay.nights, 2);

  const shortFebruary = validateRange('2026-02-27', '2026-02-28');
  assert.strictEqual(shortFebruary.ok, true);
  assert.strictEqual(shortFebruary.nights, 1);

  const yearEnd = validateRange('2026-12-30', '2026-12-31');
  assert.strictEqual(yearEnd.ok, true);
  assert.strictEqual(yearEnd.nights, 1);
});

test('s6 a quote carries the rejection code and a day-use stay prices from its own rate', () => {
  const inverted = quoteStay({ checkIn: '2026-04-18', checkOut: '2026-04-11', nightlyRate: 120 });
  assert.strictEqual(inverted.quoted, false);
  assert.strictEqual(inverted.code, 'inverted', 'the validator code reaches the UI');
  assert.ok(typeof inverted.message === 'string' && inverted.message.length > 0, 'the code sits beside the message, it does not replace it');

  const tooLong = quoteStay({ checkIn: '2026-01-01', checkOut: '2026-02-15', nightlyRate: 120 });
  assert.strictEqual(tooLong.quoted, false);
  assert.strictEqual(tooLong.code, 'too_long');
  assert.ok(typeof tooLong.message === 'string' && tooLong.message.length > 0);

  const dayUse = quoteStay({ checkIn: '2026-03-09', checkOut: '2026-03-09', nightlyRate: 120, dayUseRate: 49.99 });
  assert.strictEqual(dayUse.quoted, true, 'a day-use booking is quotable');
  assert.strictEqual(dayUse.nights, 0);
  assert.strictEqual(dayUse.total, 49.99, 'day use prices from the day-use rate, not from zero nights');

  const noDayRate = quoteStay({ checkIn: '2026-03-09', checkOut: '2026-03-09', nightlyRate: 120 });
  assert.strictEqual(noDayRate.quoted, false, 'no day-use rate means no day-use quote');
  assert.strictEqual(noDayRate.code, 'no_day_use_rate');
  assert.ok(typeof noDayRate.message === 'string' && noDayRate.message.length > 0);

  const overnight = quoteStay({ checkIn: '2026-05-01', checkOut: '2026-05-04', nightlyRate: 100 });
  assert.strictEqual(overnight.quoted, true, 'an ordinary stay still quotes on the nightly rate');
  assert.strictEqual(overnight.nights, 3);
  assert.strictEqual(overnight.total, 300);
});

test('s7 a per-property night cap overrides the default and the reason names the cap that applied', () => {
  const overCustom = validateRange('2026-01-01', '2026-01-10', { maxNights: 7 });
  assert.strictEqual(overCustom.ok, false, '9 nights is over a 7 night cap');
  assert.strictEqual(overCustom.code, 'too_long');
  assert.ok(String(overCustom.reason).includes('7'), 'the reason names the cap that applied');

  const atCustom = validateRange('2026-01-01', '2026-01-08', { maxNights: 7 });
  assert.strictEqual(atCustom.ok, true, 'exactly the custom cap is allowed');
  assert.strictEqual(atCustom.nights, 7);

  const longerCap = validateRange('2026-01-01', '2026-03-01', { maxNights: 90 });
  assert.strictEqual(longerCap.ok, true, 'a longer cap lets a longer stay through');
  assert.strictEqual(longerCap.nights, 59);

  for (const junk of [0, -5, 7.5, '7', null, NaN, Infinity, true]) {
    const over = validateRange('2026-01-01', '2026-02-15', { maxNights: junk });
    assert.strictEqual(over.ok, false, 'an unusable cap falls back to 30, and 45 nights is over 30');
    assert.strictEqual(over.code, 'too_long');
    assert.ok(String(over.reason).includes('30'), 'the reason names the cap that applied');

    const under = validateRange('2026-01-01', '2026-01-10', { maxNights: junk });
    assert.strictEqual(under.ok, true, 'an unusable cap falls back to 30, and 9 nights is inside 30');
    assert.strictEqual(under.nights, 9);
  }

  const noOptions = validateRange('2026-01-01', '2026-02-15');
  assert.strictEqual(noOptions.code, 'too_long', 'the default cap still applies with no options at all');
  assert.ok(String(noOptions.reason).includes('30'), 'the reason names the cap that applied');
});

test('s8 a blackout date inside the occupied nights rejects, and the check-out day is not one', () => {
  const midStay = validateRange('2026-05-10', '2026-05-14', { blackout: ['2026-05-12'] });
  assert.strictEqual(midStay.ok, false, 'a blacked out night inside the stay is a rejection');
  assert.strictEqual(midStay.code, 'blackout');
  assert.strictEqual(midStay.on, '2026-05-12', 'the rejection names the offending date');
  assert.ok(typeof midStay.reason === 'string' && midStay.reason.length > 0);

  const arrivalDay = validateRange('2026-05-10', '2026-05-14', { blackout: ['2026-05-10'] });
  assert.strictEqual(arrivalDay.ok, false, 'the check-in day is occupied');
  assert.strictEqual(arrivalDay.code, 'blackout');
  assert.strictEqual(arrivalDay.on, '2026-05-10');

  const departureDay = validateRange('2026-05-10', '2026-05-14', { blackout: ['2026-05-14'] });
  assert.strictEqual(departureDay.ok, true, 'the guest is gone before the check-out day is occupied');
  assert.strictEqual(departureDay.nights, 4);

  const outsideTheStay = validateRange('2026-05-10', '2026-05-14', { blackout: ['2026-05-09', '2026-06-01'] });
  assert.strictEqual(outsideTheStay.ok, true, 'blackout dates outside the stay are irrelevant');
  assert.strictEqual(outsideTheStay.nights, 4);

  const several = validateRange('2026-05-10', '2026-05-16', { blackout: ['2026-05-14', '2026-05-11', '2026-05-13'] });
  assert.strictEqual(several.ok, false);
  assert.strictEqual(several.on, '2026-05-11', 'the earliest blacked out night, not the first one in the list');

  const dayUse = validateRange('2026-07-04', '2026-07-04', { blackout: ['2026-07-04'] });
  assert.strictEqual(dayUse.ok, false, 'a day-use booking occupies the single day it sits on');
  assert.strictEqual(dayUse.code, 'blackout');
  assert.strictEqual(dayUse.on, '2026-07-04');

  const dayUseElsewhere = validateRange('2026-07-05', '2026-07-05', { blackout: ['2026-07-04'] });
  assert.strictEqual(dayUseElsewhere.ok, true, 'a day-use booking the day after a closure is fine');
  assert.strictEqual(dayUseElsewhere.nights, 0);

  const emptyList = validateRange('2026-05-10', '2026-05-14', { blackout: [] });
  assert.strictEqual(emptyList.ok, true, 'an empty blackout list blocks nothing');
  const noList = validateRange('2026-05-10', '2026-05-14', {});
  assert.strictEqual(noList.ok, true, 'no blackout list blocks nothing');
});

test('s9 totals are rounded to whole cents and an unusable nightly rate is refused', () => {
  const awkward = quoteStay({ checkIn: '2026-05-01', checkOut: '2026-05-04', nightlyRate: 20.15 });
  assert.strictEqual(awkward.quoted, true);
  assert.strictEqual(awkward.nights, 3);
  assert.strictEqual(awkward.total, 60.45, 'three nights at 20.15 is 60.45, not 60.449999999999996');

  const pennies = quoteStay({ checkIn: '2026-05-01', checkOut: '2026-05-04', nightlyRate: 0.1 });
  assert.strictEqual(pennies.total, 0.3);

  const dayUse = quoteStay({ checkIn: '2026-05-01', checkOut: '2026-05-01', dayUseRate: 100 / 3 });
  assert.strictEqual(dayUse.quoted, true);
  assert.strictEqual(dayUse.total, 33.33, 'day-use quotes are rounded to cents too');

  for (const junk of [0, -10, '120', null, undefined, NaN, Infinity]) {
    const bad = quoteStay({ checkIn: '2026-05-01', checkOut: '2026-05-04', nightlyRate: junk });
    assert.strictEqual(bad.quoted, false, 'an unusable nightly rate is refused rather than quoted');
    assert.strictEqual(bad.code, 'bad_rate');
    assert.ok(typeof bad.message === 'string' && bad.message.length > 0);
  }

  const ordinary = quoteStay({ checkIn: '2026-05-01', checkOut: '2026-05-04', nightlyRate: 150 });
  assert.strictEqual(ordinary.quoted, true, 'a good rate still quotes');
  assert.strictEqual(ordinary.total, 450);
});

test('s10 overlaps tells a genuine clash from a turnover', () => {
  const stay = { start: '2026-05-01', end: '2026-05-05' };

  assert.strictEqual(overlaps(stay, { start: '2026-05-03', end: '2026-05-08' }), true, 'a straddling stay clashes');
  assert.strictEqual(overlaps({ start: '2026-05-03', end: '2026-05-08' }, stay), true, 'the answer does not depend on argument order');
  assert.strictEqual(overlaps(stay, { start: '2026-05-02', end: '2026-05-03' }), true, 'a contained stay clashes');
  assert.strictEqual(overlaps({ start: '2026-04-20', end: '2026-05-20' }, stay), true, 'a containing stay clashes');
  assert.strictEqual(overlaps(stay, stay), true, 'an identical stay clashes');

  assert.strictEqual(overlaps(stay, { start: '2026-05-05', end: '2026-05-09' }), false, 'a turnover on the check-out day is not a clash');
  assert.strictEqual(overlaps(stay, { start: '2026-04-27', end: '2026-05-01' }), false, 'the stay before it, ending on the check-in day, is not a clash');
  assert.strictEqual(overlaps(stay, { start: '2026-05-06', end: '2026-05-09' }), false, 'a stay well after it is not a clash');
  assert.strictEqual(overlaps(stay, { start: '2026-04-20', end: '2026-04-25' }), false, 'a stay well before it is not a clash');

  assert.strictEqual(overlaps(stay, { start: '2026-05-04', end: '2026-05-04' }), true, 'a day-use booking on an occupied date clashes');
  assert.strictEqual(overlaps(stay, { start: '2026-05-01', end: '2026-05-01' }), true, 'a day-use booking on the check-in date clashes');
  assert.strictEqual(overlaps(stay, { start: '2026-05-05', end: '2026-05-05' }), false, 'a day-use booking on the check-out date is free');
  assert.strictEqual(overlaps({ start: '2026-05-04', end: '2026-05-04' }, { start: '2026-05-04', end: '2026-05-04' }), true, 'two day-use bookings on the same date clash');

  assert.strictEqual(overlaps(stay, { start: 'sometime in may', end: '2026-05-03' }), false, 'a range it cannot read is not an overlap');
  assert.strictEqual(overlaps(stay, { start: '2026-02-30', end: '2026-05-03' }), false, 'an impossible date is not an overlap');
  assert.strictEqual(overlaps(stay, { start: '2026-05-08', end: '2026-05-03' }), false, 'a backwards range is not an overlap');
  assert.strictEqual(overlaps(stay, null), false, 'a missing range is not an overlap');
});

test('s11 the booking window applies only with a today, and the rejection order is fixed', () => {
  const today = '2026-05-10';

  const past = validateRange('2026-05-01', '2026-05-05', { today });
  assert.strictEqual(past.ok, false, 'a check-in before today is rejected');
  assert.strictEqual(past.code, 'past');
  assert.ok(typeof past.reason === 'string' && past.reason.length > 0);

  const startsToday = validateRange('2026-05-10', '2026-05-12', { today });
  assert.strictEqual(startsToday.ok, true, 'a check-in on today itself is fine');
  assert.strictEqual(startsToday.nights, 2);

  const atWindowEdge = validateRange('2026-06-09', '2026-06-11', { today, maxAdvanceDays: 30 });
  assert.strictEqual(atWindowEdge.ok, true, 'exactly maxAdvanceDays ahead is still inside the window');

  const pastWindow = validateRange('2026-06-10', '2026-06-12', { today, maxAdvanceDays: 30 });
  assert.strictEqual(pastWindow.ok, false, 'one day beyond the window is outside it');
  assert.strictEqual(pastWindow.code, 'too_far');
  assert.ok(typeof pastWindow.reason === 'string' && pastWindow.reason.length > 0);

  const noWindowGiven = validateRange('2026-12-01', '2026-12-05', { today });
  assert.strictEqual(noWindowGiven.ok, true, 'without maxAdvanceDays there is no far limit');

  for (const junk of [-1, 2.5, '30', null, NaN]) {
    const ignored = validateRange('2026-12-01', '2026-12-05', { today, maxAdvanceDays: junk });
    assert.strictEqual(ignored.ok, true, 'an unusable maxAdvanceDays imposes no window');
  }

  const zeroWindow = validateRange('2026-05-11', '2026-05-13', { today, maxAdvanceDays: 0 });
  assert.strictEqual(zeroWindow.ok, false, 'a zero day window is a real window, not a missing one');
  assert.strictEqual(zeroWindow.code, 'too_far');

  const importer = validateRange('2019-03-01', '2019-03-05');
  assert.strictEqual(importer.ok, true, 'with no today at all a historic reservation still validates');
  assert.strictEqual(importer.nights, 4);
  const importerWithOtherOptions = validateRange('2019-03-01', '2019-03-05', { maxNights: 30 });
  assert.strictEqual(importerWithOtherOptions.ok, true, 'other options do not switch the window on');

  // One code out, even when several rules are broken at once.
  assert.strictEqual(validateRange('2026-02-30', '2026-01-01', { today }).code, 'bad_format', 'bad_format outranks inverted');
  assert.strictEqual(validateRange('2026-05-05', '2026-05-01', { today }).code, 'inverted', 'inverted outranks past');
  assert.strictEqual(validateRange('2026-01-01', '2026-03-01', { today }).code, 'past', 'past outranks too_long');
  assert.strictEqual(validateRange('2026-12-01', '2027-02-01', { today, maxAdvanceDays: 30 }).code, 'too_far', 'too_far outranks too_long');
  assert.strictEqual(validateRange('2026-06-01', '2026-08-01', { blackout: ['2026-06-05'] }).code, 'too_long', 'too_long outranks blackout');
});

test('s12 nightsByMonth splits the occupied nights across calendar months', () => {
  assert.deepStrictEqual(nightsByMonth('2026-01-30', '2026-02-02'), { '2026-01': 2, '2026-02': 1 }, 'two nights in January, one in February');
  assert.deepStrictEqual(nightsByMonth('2026-05-01', '2026-05-04'), { '2026-05': 3 }, 'a stay inside one month is one key');
  assert.deepStrictEqual(nightsByMonth('2026-12-30', '2027-01-02'), { '2026-12': 2, '2027-01': 1 }, 'a stay over a year boundary splits');
  // The same two calendar days in a leap year and in a common year: 2028 has a
  // 29th to sleep in and 2027 does not.
  assert.deepStrictEqual(nightsByMonth('2028-02-26', '2028-03-01'), { '2028-02': 4 }, 'a leap February has a 29th to sleep in');
  assert.deepStrictEqual(nightsByMonth('2027-02-26', '2027-03-01'), { '2027-02': 3 }, 'a common February stops at the 28th');
  assert.deepStrictEqual(nightsByMonth('2026-04-28', '2026-06-02'), { '2026-04': 3, '2026-05': 31, '2026-06': 1 }, 'the 30 night cap does not apply to a reporting helper');

  assert.deepStrictEqual(nightsByMonth('2026-03-09', '2026-03-09'), {}, 'a day-use booking has no nights');
  assert.strictEqual(nightsByMonth('2026-03-09', '2026-03-01'), null, 'a backwards range has no answer');
  assert.strictEqual(nightsByMonth('2026-02-30', '2026-03-05'), null, 'an impossible date has no answer');
  assert.strictEqual(nightsByMonth('next tuesday', '2026-03-05'), null, 'an unreadable date has no answer');

  const split = nightsByMonth('2026-01-30', '2026-02-02');
  const summed = Object.keys(split).reduce((acc, key) => acc + split[key], 0);
  assert.strictEqual(summed, validateRange('2026-01-30', '2026-02-02').nights, 'the split adds up to the night count');
});

