'use strict';

// Booking date ranges. The reservation form hands us the two calendar days as
// 'YYYY-MM-DD' strings; a stay is counted in nights between those two days.

const DAY_MS = 24 * 60 * 60 * 1000;
const MAX_STAY_NIGHTS = 30;

function toUtcDay(value) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value).trim());
  if (!m) return null;
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  const stamp = Date.UTC(year, month - 1, day);
  const back = new Date(stamp);
  // Date.UTC rolls impossible days forward, so 2026-02-30 becomes March 2nd
  // unless the round trip is checked.
  if (
    back.getUTCFullYear() !== year ||
    back.getUTCMonth() !== month - 1 ||
    back.getUTCDate() !== day
  ) {
    return null;
  }
  return stamp;
}

function toDayString(stamp) {
  const d = new Date(stamp);
  const pad = (n, width) => String(n).padStart(width, '0');
  return pad(d.getUTCFullYear(), 4) + '-' + pad(d.getUTCMonth() + 1, 2) + '-' + pad(d.getUTCDate(), 2);
}

function nightsBetween(startDay, endDay) {
  return Math.round((endDay - startDay) / DAY_MS);
}

function capFrom(options) {
  const raw = options.maxNights;
  if (typeof raw === 'number' && Number.isInteger(raw) && raw > 0) return raw;
  return MAX_STAY_NIGHTS;
}

// The days a guest is actually in the room: check-in and every night after it,
// never the check-out day. A day-use booking holds the single day it sits on.
function occupiedDays(startDay, endDay) {
  if (endDay === startDay) return [startDay];
  const days = [];
  for (let d = startDay; d < endDay; d += DAY_MS) days.push(d);
  return days;
}

function firstBlackout(startDay, endDay, list) {
  if (!Array.isArray(list) || list.length === 0) return null;
  const closed = new Set(list.map((d) => String(d).trim()));
  for (const stamp of occupiedDays(startDay, endDay)) {
    const key = toDayString(stamp);
    if (closed.has(key)) return key;
  }
  return null;
}

// Rejection order is load bearing: bad_format, inverted, past, too_far,
// too_long, blackout.
function validateRange(start, end, options) {
  const opts = options && typeof options === 'object' ? options : {};
  const startDay = toUtcDay(start);
  const endDay = toUtcDay(end);
  if (startDay === null || endDay === null) {
    return {
      ok: false,
      code: 'bad_format',
      reason: 'dates must be a real calendar day written as YYYY-MM-DD',
    };
  }
  if (endDay < startDay) {
    return { ok: false, code: 'inverted', reason: 'check-out cannot fall before check-in' };
  }
  const today = toUtcDay(opts.today);
  if (today !== null) {
    if (startDay < today) {
      return { ok: false, code: 'past', reason: 'check-in has already passed' };
    }
    const window = opts.maxAdvanceDays;
    if (typeof window === 'number' && Number.isInteger(window) && window >= 0) {
      if (startDay > today + window * DAY_MS) {
        return {
          ok: false,
          code: 'too_far',
          reason: 'check-in cannot be more than ' + window + ' days ahead',
        };
      }
    }
  }
  const nights = nightsBetween(startDay, endDay);
  const cap = capFrom(opts);
  if (nights > cap) {
    return {
      ok: false,
      code: 'too_long',
      reason: 'a stay cannot run longer than ' + cap + ' nights',
    };
  }
  const closedOn = firstBlackout(startDay, endDay, opts.blackout);
  if (closedOn !== null) {
    return {
      ok: false,
      code: 'blackout',
      on: closedOn,
      reason: 'the property is closed on ' + closedOn,
    };
  }
  return { ok: true, nights };
}

// Half open occupancy interval [from, to) for a stay, or null if the stay is
// not readable. A turnover shares an endpoint and therefore does not overlap.
function occupancy(range) {
  if (!range || typeof range !== 'object') return null;
  const from = toUtcDay(range.start);
  const to = toUtcDay(range.end);
  if (from === null || to === null || to < from) return null;
  return { from, to: to === from ? from + DAY_MS : to };
}

function overlaps(a, b) {
  const left = occupancy(a);
  const right = occupancy(b);
  if (left === null || right === null) return false;
  return left.from < right.to && right.from < left.to;
}

function nightsByMonth(start, end) {
  const startDay = toUtcDay(start);
  const endDay = toUtcDay(end);
  if (startDay === null || endDay === null || endDay < startDay) return null;
  const out = {};
  for (let d = startDay; d < endDay; d += DAY_MS) {
    const key = toDayString(d).slice(0, 7);
    out[key] = (out[key] || 0) + 1;
  }
  return out;
}

module.exports = { validateRange, nightsBetween, overlaps, nightsByMonth };

