'use strict';

const { validateRange } = require('./range.js');

// Money leaves this file in whole cents. The multiply below used to hand
// 60.449999999999996 straight to the guest-facing screen.
function toCents(amount) {
  return Math.round(amount * 100) / 100;
}

function usableRate(value) {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

// Prices a stay for the reservation form. Whatever the validator turns down is
// echoed back to the guest, so the reason has to read like a sentence, and the
// UI switches on the code beside it.
function quoteStay(request) {
  const req = request && typeof request === 'object' ? request : {};
  const range = validateRange(req.checkIn, req.checkOut);
  if (!range.ok) {
    return { quoted: false, code: range.code, message: range.reason };
  }
  if (range.nights === 0) {
    if (!usableRate(req.dayUseRate)) {
      return {
        quoted: false,
        code: 'no_day_use_rate',
        message: 'a day-use booking needs a day-use rate',
      };
    }
    return { quoted: true, nights: 0, total: toCents(req.dayUseRate) };
  }
  if (!usableRate(req.nightlyRate)) {
    return {
      quoted: false,
      code: 'bad_rate',
      message: 'the nightly rate must be a positive number',
    };
  }
  return {
    quoted: true,
    nights: range.nights,
    total: toCents(range.nights * req.nightlyRate),
  };
}

module.exports = { quoteStay };
